from machine import Pin, SPI


class MAX7219:
    def __init__(self, spi, cs, digits=8):
        self.spi = spi
        self.cs = Pin(cs, Pin.OUT, value=1)
        for reg, val in ((0x0F, 0), (0x0C, 0), (0x0B, digits - 1), (0x09, 0xFF), (0x0A, 8), (0x0C, 1)):
            self._reg(reg, val)

    def _reg(self, reg, val):
        self.cs(0)
        self.spi.write(bytes((reg, val)))
        self.cs(1)

    def number(self, n):
        s = '%8d' % n
        for i, c in enumerate(reversed(s)):
            self._reg(i + 1, 0x0F if c == ' ' else (0x0A if c == '-' else int(c)))
